from math import gcd

class Solution:
    def selfDivisiblePermutationCount(self, n: int) -> int:
        # dp[mask] = number of ways to fill the first popcount(mask) positions
        # using exactly the numbers whose bits are set in mask
        dp = [0] * (1 << n)
        dp[0] = 1
        for mask in range(1 << n):
            if dp[mask] == 0:
                continue
            pos = bin(mask).count('1') + 1  # next position to fill (1-indexed)
            if pos > n:
                continue
            for num in range(1, n + 1):
                bit = 1 << (num - 1)
                if not (mask & bit) and gcd(num, pos) == 1:
                    dp[mask | bit] += dp[mask]
        return dp[(1 << n) - 1]
